import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeSet;
import java.util.function.Function;
import java.util.function.Predicate;

public class RepositoryMasteryDemo {

    // Generic Repository Contract
    public interface Repository<T, ID> {
        void save(T entity);
        Optional<T> findById(ID id);
        List<T> findAll();
        List<T> findWhere(Predicate<? super T> predicate);
        boolean deleteById(ID id);
        int count();
    }

    // In-Memory Repository Implementation
    public static class InMemoryRepository<T, ID> implements Repository<T, ID> {
        private final Map<ID, T> storage = new HashMap<>();
        private final TreeSet<T> sortedIndex;
        private final Function<T, ID> idExtractor;

        public InMemoryRepository(Function<T, ID> idExtractor, Comparator<? super T> comparator) {
            this.idExtractor = idExtractor;
            this.sortedIndex = new TreeSet<>(comparator);
        }

        @Override
        public void save(T entity) {
            if (entity == null) throw new IllegalArgumentException("Entity cannot be null");
            ID id = idExtractor.apply(entity);
            if (id == null) throw new IllegalArgumentException("Entity ID cannot be null");

            // Remove previous entity version from sorted index if updating
            T existing = storage.get(id);
            if (existing != null) {
                sortedIndex.remove(existing);
            }

            storage.put(id, entity);
            sortedIndex.add(entity);
        }

        @Override
        public Optional<T> findById(ID id) {
            if (id == null) return Optional.empty();
            return Optional.ofNullable(storage.get(id));
        }

        @Override
        public List<T> findAll() {
            return List.copyOf(sortedIndex); // returns sorted immutable snapshot
        }

        @Override
        public List<T> findWhere(Predicate<? super T> predicate) {
            List<T> matching = new ArrayList<>();
            for (T item : sortedIndex) {
                if (predicate.test(item)) {
                    matching.add(item);
                }
            }
            return List.copyOf(matching);
        }

        @Override
        public boolean deleteById(ID id) {
            if (id == null) return false;
            T removed = storage.remove(id);
            if (removed != null) {
                sortedIndex.remove(removed);
                return true;
            }
            return false;
        }

        @Override
        public int count() {
            return storage.size();
        }
    }

    // Domain Entity
    static class Employee {
        final String id;
        final String name;
        final int salary;

        Employee(String id, String name, int salary) {
            this.id = id;
            this.name = name;
            this.salary = salary;
        }

        @Override
        public String toString() {
            return id + ":" + name + "($" + salary + ")";
        }
    }

    public static void main(String[] args) {
        // Order employees by salary descending, then by name
        Comparator<Employee> salaryOrder = Comparator
            .comparingInt((Employee e) -> e.salary).reversed()
            .thenComparing(e -> e.name);

        Repository<Employee, String> repo = new InMemoryRepository<>(e -> e.id, salaryOrder);

        repo.save(new Employee("E101", "Alice", 95000));
        repo.save(new Employee("E102", "Bob", 72000));
        repo.save(new Employee("E103", "Charlie", 120000));

        System.out.println("Total count: " + repo.count());
        System.out.println("All employees sorted by salary: " + repo.findAll());

        // Find by ID
        Optional<Employee> alice = repo.findById("E101");
        alice.ifPresent(e -> System.out.println("Found by ID: " + e));

        // Predicate query
        List<Employee> highEarners = repo.findWhere(e -> e.salary > 80000);
        System.out.println("Employees earning > 80k: " + highEarners);

        // Update entity
        repo.save(new Employee("E102", "Bob", 130000));
        System.out.println("After Bob promotion, order: " + repo.findAll());

        // Delete
        repo.deleteById("E101");
        System.out.println("After Alice deletion, count: " + repo.count());
    }
}
```

