import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class SecondaryIndex<ID, Tag> {
    private final Map<Tag, Set<ID>> tagIndex = new HashMap<>();

    public void addTag(ID id, Tag tag) {
        if (id != null && tag != null) {
            tagIndex.computeIfAbsent(tag, k -> new HashSet<>()).add(id);
        }
    }

    public void removeTag(ID id, Tag tag) {
        if (id != null && tag != null) {
            Set<ID> set = tagIndex.get(tag);
            if (set != null) {
                set.remove(id);
                if (set.isEmpty()) {
                    tagIndex.remove(tag);
                }
            }
        }
    }

    public Set<ID> findByTag(Tag tag) {
        if (tag == null) return Set.of();
        Set<ID> set = tagIndex.get(tag);
        return set == null ? Set.of() : Set.copyOf(set);
    }
}

